$PSNativeCommandUseErrorActionPreference=$false
$timer=[Diagnostics.Stopwatch]::StartNew(); $budget=1800; $delay=10
for ($i=0; $i -le 180; $i++) {
  $remaining=[int][Math]::Ceiling($budget-$timer.Elapsed.TotalSeconds); if ($remaining -le 0) { break }
  $timeout=[Math]::Min(20,$remaining)
  $response=@(curl.exe -s --connect-timeout 10 --max-time $timeout -w '\n%{http_code}' -- 'https://ai-generator.tuanjie.cn/api/task/6b0688d7fa11799b31419546/status?poll_token=6b06a4f8.14f537d1a853663420a171985e94a8d42e01060330fef3e905187cc46353b597'); $rc=$LASTEXITCODE
  if ($rc -eq 0 -and $response.Count -gt 0) {
    $code=[string]$response[-1]; $body=''
    if ($response.Count -gt 1) { $body=$response[0..($response.Count-2)] -join [Environment]::NewLine }
    if ($code -eq '200') {
      try { $status=($body | ConvertFrom-Json -ErrorAction Stop).status } catch { $status=$null }
      if ($status -in @('completed','failed','cancelled')) { Write-Output $body; exit 0 }
      if ($status -notin @('pending','queued','running','retrying')) { Write-Output '{"poll_error":"invalid_response","next_action":"check_task"}'; exit 3 }
      $delay=10
    } elseif ($code -in @('401','403')) {
      Write-Output ('{"poll_error":"authorization","http_status":'+$code+',"next_action":"check_task"}'); exit 2
    } elseif ($code -eq '429' -or $code -match '^5\d\d$') {
      $delay*=2
    } else {
      Write-Output ('{"poll_error":"http_error","http_status":'+$code+',"next_action":"check_task"}'); exit 3
    }
  } else { $delay*=2 }
  if ($i -ge 180) { break }
  $delay=[Math]::Min(60,$delay)
  $remaining=$budget-$timer.Elapsed.TotalSeconds; if ($remaining -le 0) { break }
  Start-Sleep -Milliseconds ([int]([Math]::Min($delay,$remaining)*1000))
}
Write-Output '{"poll_error":"timeout","next_action":"check_task"}'; exit 124

